from datetime import datetime, timezone

def get_local_deadline():
    return datetime(2026, 8, 20, 17, 0)   # naive -- no timezone attached

def get_server_event_time():
    return datetime(2026, 8, 18, 12, 0, tzinfo=timezone.utc)   # aware -- explicitly UTC

deadline = get_local_deadline()
event_time = get_server_event_time()

try:
    if event_time < deadline:
        print("Event happens before the deadline")
except TypeError as e:
    print(f"Comparison failed: {e}")

# Fix: make both aware (or both naive) before comparing
from datetime import timezone as tz
aware_deadline = deadline.replace(tzinfo=tz.utc)   # explicitly declare it as UTC
print(event_time < aware_deadline)   # now this works: True
